+      </div>
+
+      <div class="form-field">
+        <h2 class="question-title">2. Which of these are widely used compiled languages?</h2>
+        <div class="choices" role="group" aria-label="Question 2">
+          <label class="choice"><input type="checkbox" name="q2" value="c"><span>C</span></label>
