   </main>

   <script>
     const form = document.getElementById('quiz-form');
     const result = document.getElementById('result');

     const answers = {
       q1: ['python', 'javascript'],
       q2: ['c', 'rust', 'java'],
       q3: ['html', 'css']
     };

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       let score = 0;

       for (const [question, expected] of Object.entries(answers)) {
         const selected = [...form.querySelectorAll(`input[name="${question}"]:checked`)].map((input) => input.value);
         const isCorrect =
           selected.length === expected.length &&
           expected.every((value) => selected.includes(value));

         if (isCorrect) score += 1;
       }

       result.textContent = `You got ${score} out of ${Object.keys(answers).length} correct.`;
     });
   </script>
 </body>
 </html>

')
